@Component("transaction-subscriber")
public class TransactionSubscriber extends BaseSubscriber {

	public TransactionSubscriber() {
	}
	
    public SubscriptionQueryResult<List<Transaction>, Transaction> transactionSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllTransactionQuery(), 
                		ResponseTypes.multipleInstancesOf(Transaction.class),
                		ResponseTypes.instanceOf(Transaction.class));
    }

    public SubscriptionQueryResult<Transaction, Transaction> transactionSubscribe(@DestinationVariable UUID transactionId) {
        return queryGateway
                .subscriptionQuery(new FindTransactionQuery(new LoadTransactionFilter(transactionId)), 
                		ResponseTypes.instanceOf(Transaction.class),
                		ResponseTypes.instanceOf(Transaction.class));
    }





}

